import {sentence,stages} from './data.js';
import {esc,icon,btn} from './views.js';
const describeHint=(l,s,modal)=>l===1?`关键词：${s.action.split(' ')[0]}，再加上你要请求的内容。`:l===2?`句子骨架：${modal} you + 动词原形 + … ?`:sentence(s,modal);
function aside(state,s){return `<aside class="practice-aside"><h2>本次学习目标</h2><p>请求对方做一件事，注意问句语序与动词原形。</p><div class="sentence-token"><strong>${state.modal} + you + 动词原形</strong><p>本课中的 could 是当下的委婉请求，不表示过去。</p></div>${s.words.map(([a,b])=>`<div class="sentence-token"><strong>${esc(a)}</strong><p>${esc(b)}</p></div>`).join('')}<p>当前场景：${esc(s.name)}<br>学习结构不随场景重置。</p></aside>`;}
function feedback(state,s){const f=state.session.feedback;if(!f)return '';const known=f.kind==='target'||f.kind==='form';return `<div class="feedback" role="status"><h2>${f.title}</h2><p>${f.body}</p>${known?`<p class="english">${esc(sentence(s,state.modal))}</p>`:''}${state.session.hints||state.session.attempts>1?'<p>本次已使用提示或重试，记录为练习后证据。</p>':''}</div>`;}
const verbs={send:'send（发送）',show:'show（指引）',explain:'explain（解释）',check:'check（核对）',help:'help（帮助）'};const words={gate:'gate（登机口）',question:'question（问题）',file:'file（文件）'};
export function practiceView(state,s){
 const session=state.session,step=session.step;
 if(step===6)return summaryView(state,s);
 const stage=step===0?0:step<=2?1:step<=4?2:3;
 let content='';
 if(step===0)content=`<h1>先找回昨天的结构。</h1><p class="muted">复习 4 分钟 · 今天先确认动词原形。</p><div class="task-context"><p class="english">Can you ___ me the file?</p><p class="small muted">在请求句中，you 后面的动词怎么用？</p></div><div class="options">${['send','sends','sending'].map((a,i)=>`<button class="option" data-action="review-choice" data-id="${i}" aria-pressed="${session.choice===i}"><span class="radio-mark" aria-hidden="true"></span>${a}</button>`).join('')}</div>${session.reviewChecked?`<div class="feedback" role="status"><h2>${session.choice===0?'对，请求句用动词原形。':'这里用 send。'}</h2><p>Can / Could 放前面，主语 you 跟在后面，再接动词原形。这次只记录结构理解，不当作独立表达证据。</p></div>`:''}<div class="practice-buttons">${btn(session.reviewChecked?'继续情境学习':'检查这题',session.reviewChecked?'next-step':'check-review','primary',session.choice===null?'disabled':'')}</div>`;
 if(step===1)content=`<h1>先听懂这个请求。</h1><p class="muted">${esc(s.name)} · ${esc(s.topic)}</p><div class="task-context"><p>${esc(s.listenQuestion)}</p>${btn(`${icon('play.fill','white')} 播放这句话`,'lesson-audio','primary')}<p class="small muted">${session.listenMode==='reading'?esc(s.listen):session.audioPlayed?'已播放完成。按你听到的意思选择。':session.audioPending?'正在播放，完成后再检查。':'先不显示英文，让意思先到达。'}</p></div><div class="options">${s.listenOptions.map((a,i)=>`<button class="option" data-action="listen-choice" data-id="${i}" aria-pressed="${session.choice===i}"><span class="radio-mark" aria-hidden="true"></span>${a}</button>`).join('')}</div>${session.listenChecked?`<div class="feedback" role="status"><h2>${session.choice===s.listenAnswer?'听到关键信息了。':'再注意一下这个信息。'}</h2><p class="english">${esc(s.listen)}</p><p>这条证据只用于本句理解，不代表整体听力水平。</p></div>`:''}<div class="practice-buttons">${btn(session.listenChecked?'看句型，理解怎样组成':'检查听到的信息',session.listenChecked?'next-step':'check-listening','primary',session.choice===null||!session.audioPlayed?'disabled':'')}${btn('改用阅读（不记听力证据）','listen-reading','text-button')}</div>`;
 if(step===2)content=`<h1>一句话，拆开再组回来。</h1><p class="muted">语法焦点：模态动词请求句 · 问句语序与动词原形</p><p class="english blue">${esc(sentence(s,state.modal))}</p>${state.support==='scaffold'||session.meaningVisible?`<p class="muted">${esc(s.meaning)}</p>`:btn('查看中文意思','show-meaning','text-button')}<div class="rule-explanation"><h2>记住结构，不只记住这一句</h2>${state.support==='scaffold'?`<div class="rule-parts"><span class="rule-part focus">${state.modal}</span><span class="rule-part">you</span><span class="rule-part focus">${esc(s.action.split(' ')[0])}</span><span class="rule-part">${esc(s.action.split(' ').slice(1).join(' '))}</span><span class="rule-part">?</span></div>`:''}<p>① ${state.modal} 放在主语 you 前面，形成请求问句。<br>② ${state.modal} 后的动作词用原形，不加 to，也不加 -s。<br>③ can 和 could 都能提出请求；本课的 could 更委婉，不是在表示过去。</p></div><div class="practice-buttons">${btn('听整句','sentence-audio','secondary')}${btn('收起示范，自己组织一句','next-step')}</div>`;
 if(step===3)content=`<h1>现在，用在你自己身上。</h1><p class="muted">示范已收起 · 先独立尝试，需要时再逐步看提示。</p><div class="task-context"><p>${esc(s.goal)}</p>${s.role?`<p class="small muted">对方：${esc(s.role)}</p>`:''}</div><label class="field">你的英文请求<textarea id="practice-answer" autocomplete="off" placeholder="写下你会怎样开口。">${esc(session.answer)}</textarea></label>${session.hints?`<p class="form-status">提示 ${session.hints} / 3：${esc(describeHint(session.hints,s,state.modal))}</p>`:''}${feedback(state,s)}<div class="practice-buttons">${btn(session.feedback?'再提交一次':'提交表达','submit-request')}${btn('一点提示','hint','text-button',session.hints>=3?'disabled':'')}${session.feedback?btn(session.feedback.kind==='target'?'继续读写':'继续（保留待确认）','next-step','secondary'):''}</div><p class="small muted" style="margin-top:18px">本原型使用少量固定表达识别；其他正确表达不会因没匹配标准答案而直接判错。语音识别待接入。</p>`;
 if(step===4)content=`<h1>读一条消息，再接一句话。</h1><p class="muted">让同一结构出现在读和写里。</p><div class="task-context"><span class="small muted">对方发来的消息</span><p class="english">${esc(s.read)}</p></div><p class="muted">回应对方：${esc(s.replyMeaning)}</p><label class="field">你的回复<textarea id="practice-answer" placeholder="先把意思写清楚，再看参考表达。">${esc(session.answer)}</textarea></label>${session.writingChecked?`<div class="feedback" role="status"><h2>对照参考，自查意思与语气。</h2><p class="english">${esc(s.reply)}</p><p>参考句先答应，再说明能做什么。你的另一种说法可能同样成立；本原型没有完整写作评估，这题不记为语法通过。</p></div>`:''}<div class="practice-buttons">${btn(session.writingChecked?'换一个情境，检验迁移':'查看回复参考',session.writingChecked?'next-step':'check-writing')}</div>`;
 if(step===5){const t=s.transfer;content=`<h1>换个地方，还能自己用吗？</h1><p class="muted">新情境 · 不显示句型骨架和英文示范</p><div class="task-context"><span class="tag">${esc(t.scene)}</span><p style="margin-top:12px">${esc(t.goal)}</p></div><p class="small muted">词汇帮助：${verbs[t.action.split(' ')[0]]||''}，${words[t.action.split(' ').at(-1)]||''}。提供新词义，保留句型的独立组织。</p><label class="field">用一句英文完成请求<textarea id="practice-answer" placeholder="这次，用你记住的结构来表达。">${esc(session.answer)}</textarea></label>${feedback(state,t)}<div class="practice-buttons">${btn('提交迁移检验','submit-transfer')}${session.feedback?btn('记录结果，今天到这里','next-step','secondary'):''}</div>`;}
 return `<section><div class="session-header">${btn('返回今日','go-today','text-button neutral')}<span>${esc(s.name)} · 24 分钟学习计划</span></div><div class="stage-list">${stages.map((a,i)=>`<div class="stage ${i===stage?'current':i<stage?'done':''}">${i+1} · ${a}</div>`).join('')}</div><div class="practice-layout"><div class="practice-content">${content}<p class="form-status" role="status">${esc(state.notice)}</p></div>${step===3?'<aside class="practice-aside"><h2>先尝试，再给提示</h2><p>这里收起句型骨架与完整示范。遇到困难时，按关键词、骨架、整句逐步展开提示。</p><p>刚学习后的无提示成功会单独记录；稳定掌握还需要迁移和间隔检验。</p></aside>':step===5?'<aside class="practice-aside"><h2>为什么换一个场景？</h2><p>在刚见过的句子里答对，是练习后的表现。这里用新的情境，观察你能否调动同一个结构。</p><p>本次迁移仍是文字表达。口语和间隔保持分别待检验。</p></aside>':aside(state,s)}</div></section>`;
}
export function summaryView(state,s){return `<section class="summary"><span class="tag accent">今天的计划已完成</span><h1>学的是句型，用的是你的生活。</h1><p class="lead">${esc(s.name)} · 请求句 · 24 分钟计划。不把演示流程的点击时间计为真实学习时长。</p><div class="summary-record"><h2>这次留下了哪些表达？</h2>${state.practiceEvidence.length?state.practiceEvidence.slice(-2).map(e=>`<div class="result-row"><div><strong>${esc(e.scene)} · ${e.type}</strong><p class="english">${esc(e.sentence)}</p></div><span class="tag accent">${esc(e.label)}</span></div>`).join(''):'<p class="muted">当前表达还待确认。未识别的答案不记为错误，也不直接记为掌握。</p>'}</div><div class="structure-note"><h2>下一次先温习，再加一点新内容。</h2><p>请求句的间隔保持仍待检验。正式版会在后续学习日安排无提示复测；本次原型不伪造隔日保持成绩。</p></div><div class="practice-buttons">${btn('查看学习档案','go-profile')}${btn('选择下次想用的场景','go-scenes','secondary')}</div></section>`;}
